package com.dating.backend.matching;
import com.dating.backend.entity.*;import com.dating.backend.service.FileStorageService;import jakarta.persistence.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.transaction.annotation.Transactional;import org.springframework.mock.web.MockMultipartFile;import org.springframework.web.server.ResponseStatusException;import java.time.*;import java.util.*;import java.io.*;import java.nio.file.*;import javax.imageio.ImageIO;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest @Transactional class ProfilePhotoHistoryTest {
 @Autowired EntityManager em;@Autowired ProfilePhotoHistoryService history;@Autowired FileStorageService files;@Autowired PrivateMediaService media;
 User user;String url;
 @BeforeEach void setup()throws Exception{user=User.builder().email(UUID.randomUUID()+"@archive.test").nickname(UUID.randomUUID().toString()).provider("LOCAL").status("ACTIVE").build();em.persist(user);var image=new java.awt.image.BufferedImage(2400,1200,java.awt.image.BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();g.setColor(java.awt.Color.ORANGE);g.fillRect(0,0,2400,1200);g.dispose();var bytes=new ByteArrayOutputStream();ImageIO.write(image,"png",bytes);url=files.storeProfileImage(user.getId(),new MockMultipartFile("file","test.png","image/png",bytes.toByteArray()));}
 @Test void compressedArchiveIsPrivateAndDeduplicated()throws Exception{assertTrue(url.endsWith(".jpg"));assertEquals(1600,ImageIO.read(media.path(url.substring(9)).toFile()).getWidth());history.archive(user.getId(),url,"REPLACED");history.archive(user.getId(),url,"REPLACED");var rows=history.list(user.getId(),0);assertEquals(1,rows.size());var image=ImageIO.read(new ByteArrayInputStream(history.photo(rows.get(0).id())));assertEquals(960,image.getWidth());assertEquals(480,image.getHeight());assertTrue(rows.get(0).expiresAt().isAfter(Instant.now().plus(Duration.ofDays(89))));assertThrows(ResponseStatusException.class,()->media.path("photo-history/"+em.find(ProfilePhotoHistory.class,rows.get(0).id()).getFilename()));assertFalse(com.dating.backend.admin.AdminFilter.allowed("SUPPORT","GET","/api/admin/photo-history/1/photo"));assertFalse(com.dating.backend.admin.AdminFilter.allowed("READ_ONLY","GET","/api/admin/photo-history/user/1"));assertTrue(com.dating.backend.admin.AdminFilter.allowed("REVIEWER","GET","/api/admin/photo-history/1/photo"));}
 @Test void expiryPurgesArchiveButKeepsCurrentlyReferencedPhoto(){em.persist(UserProfileImage.builder().userId(user.getId()).imageUrl(url).isMain(true).imageOrder(0).build());history.archive(user.getId(),url,"REPLACED");var row=em.find(ProfilePhotoHistory.class,history.list(user.getId(),0).get(0).id());row.setExpiresAt(Instant.now().minusSeconds(1));assertThrows(ResponseStatusException.class,()->history.photo(row.getId()));history.purge();assertNotNull(row.getPurgedAt());assertNull(row.getFilename());assertTrue(Files.exists(media.path(url.substring(9))));}
 @Test void unreferencedOriginalIsRemovedAfterCompressedCopyExists(){history.archive(user.getId(),url,"DELETED");var id=history.list(user.getId(),0).get(0).id();history.purge();assertThrows(ResponseStatusException.class,()->media.path(url.substring(9)));assertTrue(history.photo(id).length>0);}
 @Test void withdrawalImmediatelyHidesHistoryAndPurgeRemovesFile(){history.archive(user.getId(),url,"DELETED");var row=em.find(ProfilePhotoHistory.class,history.list(user.getId(),0).get(0).id());history.withdraw(user.getId());user.setStatus("DELETED");assertTrue(history.list(user.getId(),0).isEmpty());assertThrows(ResponseStatusException.class,()->history.photo(row.getId()));history.purge();assertNull(row.getFilename());assertNotNull(row.getPurgedAt());}
}
